sqlEquivalent:
CREATE TABLE lab_publishers (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL);
CREATE TABLE lab_magazines (
  id SERIAL PRIMARY KEY,
  title VARCHAR(200) NOT NULL,
  publisher_id INTEGER NOT NULL REFERENCES lab_publishers(id)
);

starterCode:
// JavaScript track — same Prisma DSL
model LabPublisher {
  id Int @id @default(autoincrement())
  name String
  magazines LabMagazine[]
  @@map("lab_publishers")
}
model LabMagazine {
  id Int @id @default(autoincrement())
  title String
  publisherId Int @map("publisher_id")
  publisher LabPublisher @relation(fields: [publisherId], references: [id])
  @@map("lab_magazines")
}

